class Solution:
    def findStrobogrammatic(self, n: int) -> list[str]:
        def helper(cur_len, total_len):
            if cur_len == 0:
                return ['']
            if cur_len == 1:
                return ['0', '1', '8']
            middles = helper(cur_len - 2, total_len)
            result = []
            for m in middles:
                for pair in [('0','0'),('1','1'),('6','9'),('8','8'),('9','6')]:
                    if pair[0] == '0' and cur_len == total_len:
                        continue
                    result.append(pair[0] + m + pair[1])
            return result
        return helper(n, n)

